window.TP3B["camara:204473"] = [{"t":"PDL","n":"1007","y":"2026","e":"Disciplina, nos termos do art. 62, § 3º, da Constituição Federal, as relações jurídicas decorrentes de atos praticados, no período de vigência da Medida Provisória nº 1.349, de 7 de abril de 2026, relativos à subvenção econômica à importação de Gás Liquefeito de Petróleo (GLP) e à apuração de elevação abusiva de preços por distribuidores de GLP.","d":"2026-10-01","o":"in_progress","s":"Aguardando Chancela e Publicação do Despacho","tr":"Apresentação de Proposição","u":"2026-10-01","ds":"Apresentação do PDL n. 1007/2026 (Projeto de Decreto Legislativo de Medida Provisória), pelo Deputado General Girão (PL/RN), que \"Disciplina, nos termos do art. 62, § 3º, da Constituição Federal, as relações jurídicas decorrentes de atos praticados, no período de vigência da Medida Provisória nº 1.349, de 7 de abril de 2026, relativos à subvenção econômica à importação de Gás Liquefeito de Petróle","id":"2647284","law":false,"r":"m"},{"t":"PDL","n":"1004","y":"2026","e":"Susta os efeitos da Resolução nº 957, de 1º de setembro de 2026, que prorroga a vigência do imposto sobre a exportação de óleos brutos de petróleo ou de minerais betuminosos.","d":"2026-09-18","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Proposição","u":"2026-09-18","ds":"Apresentação do PDL n. 1004/2026 (Projeto de Decreto Legislativo de Sustação de Atos Normativos do Poder Executivo), pelo Deputado General Girão (PL/RN), que \"Susta os efeitos da Resolução nº 957, de 1º de setembro de 2026, que prorroga a vigência do imposto sobre a exportação de óleos brutos de petróleo ou de minerais betuminosos\".","id":"2646822","law":false,"r":"m"},{"t":"PDL","n":"1003","y":"2026","e":"Susta a Resolução ANP nº 1.005, de 1º de julho de 2026, que estabelece os critérios para a caracterização da elevação abusiva dos preços de combustíveis por parte de revendedores varejistas de combustíveis líquidos e de gás liquefeito de petróleo (GLP).","d":"2026-09-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Proposição","u":"2026-09-16","ds":"Apresentação do PDL n. 1003/2026 (Projeto de Decreto Legislativo de Sustação de Atos Normativos do Poder Executivo), pelo Deputado General Girão (PL/RN), que \"Susta a Resolução ANP nº 1.005, de 1º de julho de 2026, que estabelece os critérios para a caracterização da elevação abusiva dos preços de combustíveis por parte de revendedores varejistas de combustíveis líquidos e de gás liquefeito de pet","id":"2646504","law":false,"r":"m"},{"t":"PDL","n":"1002","y":"2026","e":"Susta a Resolução ANP nº 1.004, de 1º de julho de 2026, que estabelece os critérios para a caracterização da elevação abusiva dos preços de combustíveis por parte de distribuidores de combustíveis líquidos e de gás liquefeito de petróleo (GLP).","d":"2026-09-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Proposição","u":"2026-09-16","ds":"Apresentação do PDL n. 1002/2026 (Projeto de Decreto Legislativo de Sustação de Atos Normativos do Poder Executivo), pelo Deputado General Girão (PL/RN), que \"Susta a Resolução ANP nº 1.004, de 1º de julho de 2026, que estabelece os critérios para a caracterização da elevação abusiva dos preços de combustíveis por parte de distribuidores de combustíveis líquidos e de gás liquefeito de petróleo (GL","id":"2646503","law":false,"r":"m"},{"t":"PEC","n":"15","y":"2026","e":"Altera os art. 150 Constituição Federal para incluir as entidades esportivas sem fins lucrativos.","d":"2026-06-17","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Notificações","u":"2026-07-20","ds":"Indeferido o Requerimento n. 3565/2026.","id":"2633488","law":false,"r":"c"},{"t":"PL","n":"2149","y":"2026","e":"Altera a Lei nº 1.001, de 21 de outubro de 1969 (Código Penal Militar), para estabelecer salvaguardas de proteção funcional ao militar de carreira no exercício de funções institucionais, dispor sobre causa especial de diminuição de pena e fixar critérios para caracterização, no âmbito penal militar, de imputações relacionadas a crimes contra o Estado Democrático de Direito previstos na legislação penal comum.","d":"2026-05-04","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-06-19","ds":"Recebimento pelo(a) CREDN.","id":"2620890","law":false,"r":"m"},{"t":"PL","n":"495","y":"2026","e":"Denomina “Rodovia Soldado Marcelo Vitor Lopes de Oliveira Filho” o trecho da BR-226, no Estado do Rio Grande do Norte, entre os Municípios de Jucurutu e Triunfo Potiguar.","d":"2026-02-11","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-04-22","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 09/04/2026 a 22/04/2026). Não foram apresentadas emendas.","id":"2602605","law":false,"r":"m"},{"t":"PEC","n":"40","y":"2025","e":"Altera o Art. 7° da Constituição Federal para prever a possibilidade de opção pelos empregados quanto à jornada de trabalho, podendo escolher entre o regime comum previsto pela Consolidação das Leis do Trabalho (CLT), ou um regime flexível baseado em horas trabalhadas.","d":"2025-10-29","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2026-02-25","ds":"Apresentação do REQ n. 3/2026 (Requerimento de Audiência Pública), pelo Deputado Domingos Sávio (PL/MG), que \"Requer realização de audiência pública acerca da redução da jornada de trabalho, conforme proposta nas PECs nº 40/2025 e nº 8/2025\".","id":"2578996","law":false,"r":"c"},{"t":"PDL","n":"800","y":"2025","e":"Susta os efeitos da Consulta Pública Processo: 50000.034372/2025-74 de 02/10/2025, emitida pela Secretaria de Nacional de Trânsito – SENATRAN, que trata de Minuta de Resolução que “normatiza os procedimentos sobre a aprendizagem, habilitação e expedição de documentos de condutores e o processo de formação do candidato à obtenção da Carteira Nacional de Habilitação ou da Autorização para Conduzir Ciclomotor”.","d":"2025-10-07","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Notificações","u":"2025-11-06","ds":"Deferido o REQ 4532/2025.","id":"2567768","law":false,"r":"c"},{"t":"PEC","n":"34","y":"2025","e":"Acrescenta o inciso IX ao art. 225, §º1 da Constituição Federal, a alínea “e” ao inciso II do art. 9º, §3º e o §14 ao art. 9º da Emenda Constitucional 132/2023 para corrigir o tratamento injusto concedido pela Reforma Tributária aos agentes que atuam no setor de reciclagem, desvalorizando os materiais recicláveis e desincentivando a economia circular.","d":"2025-09-03","o":"in_progress","s":"Aguardando Constituição de Comissão Temporária","tr":"Expedição de Documento","u":"2026-07-06","ds":"Ato da Presidência: Cria Comissão Especial, nos termos do § 2º do art. 202 do Regimento Interno. Publicado em DCD Extra no dia 06/07/2026.","id":"2557024","law":false,"r":"c"},{"t":"PEC","n":"32","y":"2025","e":"Esta Lei altera o artigo 5º, inciso XLIII, da Constituição Federal, o qual prevê que nos casos de crimes previstos neste inciso, a pena deverá ser cumprida integralmente em regime fechado, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem, e dá outras providências.","d":"2025-08-20","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2026-09-01","ds":"Aprovado o requerimento nº 1/2026,da Sra. Talíria Petrone que requer a realização de Audiência Pública no âmbito da Comissão Especial sobre a redução da maioridade penal (PEC 32/2015) para debater a idade penal como cláusula pétrea e o controle de constitucionalidade da redução frente aos direitos e garantias individuais imutáveis da Constituição de 1988, sugerindo os seguintes especialistas: Dr. ","id":"2551011","law":false,"r":"c"},{"t":"PL","n":"3798","y":"2025","e":"Dispõe sobre vedações à atuação de magistrados no exercício da função jurisdicional, com o objetivo de preservar os princípios constitucionais do devido processo legal, imparcialidade, juiz natural, liberdade de expressão e separação de Poderes.","d":"2025-08-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-08-06","ds":"Apresentação do PL n. 3798/2025 (Projeto de Lei), pelos Deputado Rodrigo da Zaeli (PL/MT) e outros, que \"Dispõe sobre vedações à atuação de magistrados no exercício da função jurisdicional, com o objetivo de preservar os princípios constitucionais do devido processo legal, imparcialidade, juiz natural, liberdade de expressão e separação de Poderes\n\".","id":"2541173","law":false,"r":"c"},{"t":"PL","n":"3681","y":"2025","e":"Dispõe sobre a aplicação de sanções administrativas e restrições a indivíduos, nacionais ou estrangeiros, responsáveis por crimes graves, incluindo tortura, tráfico de drogas, corrupção, violação de direitos humanos, entre outros, e dá outras providências.","d":"2025-08-04","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2025-09-02","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 03/09/2025.","id":"2539268","law":false,"r":"c"},{"t":"PL","n":"3622","y":"2025","e":"Extingue a cobrança do Imposto sobre Operações de Crédito, Câmbio e Seguro, ou relativas a Títulos ou Valores Mobiliários – IOF, por meio da revogação de sua disciplina infraconstitucional.","d":"2025-07-21","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-10-01","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 02/10/2025.","id":"2538430","law":false,"r":"c"},{"t":"PDL","n":"506","y":"2025","e":"Susta os efeitos do Decreto nº 12.551, de 14 de julho de 2025, que regulamenta a Lei nº 15.122, de 11 de abril de 2025 (Lei de Reciprocidade Econômica), que “Estabelece critérios para suspensão de concessões comerciais, de investimentos e de obrigações relativas a direitos de propriedade intelectual em resposta a medidas unilaterais adotadas por país ou bloco econômico que impactem negativamente a competitividade internacional brasileira; e dá outras providências”.","d":"2025-07-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2025-07-16","ds":"Apresentação do PDL n. 506/2025 (Projeto de Decreto Legislativo), pelas Deputada Rosangela Moro (UNIÃO/SP) e outros, que \"Susta os efeitos do Decreto nº 12.551, de 14 de julho de 2025, que regulamenta a Lei nº 15.122, de 11 de abril de 2025 (Lei de Reciprocidade Econômica), que “Estabelece critérios para suspensão de concessões comerciais, de investimentos e de obrigações relativas a direitos de p","id":"2537338","law":false,"r":"c"},{"t":"PL","n":"3191","y":"2025","e":"Altera a Lei nº 10.741, de 1º de outubro de 2003 (Estatuto da Pessoa Idosa), para tornar crime a fraude e a apropriação indébita de recursos da seguridade social destinados a pessoa idosa e de descontos irregulares a título de empréstimo consignado, e a Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), para classificar como hediondo os crimes que especifica.","d":"2025-07-02","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-04-05","ds":"Apense-se a este o PL 4952/2025","id":"2531188","law":false,"r":"m"},{"t":"PDL","n":"346","y":"2025","e":"Susta os efeitos da Resolução nº 265, de 12 de junho de 2025, do Conselho Nacional dos Direitos da Criança e do Adolescente (CONANDA), que estabelece diretrizes para o enfrentamento das violências sexuais contra crianças e adolescentes, por extrapolar os limites da competência regulamentar e contrariar preceitos constitucionais e legais.","d":"2025-06-24","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2025-08-12","ds":"Apresentação do REQ n. 3219/2025 (Requerimento), pela Deputada Laura Carneiro (PSD/RJ), que \"Requer o apensamento dos Projetos de Decreto Legislativo n.º 345/2025 e 346/2025 ao Projeto de Decreto Legislativo n.º 343/2025\".","id":"2527743","law":false,"r":"c"},{"t":"PDL","n":"228","y":"2025","e":"Susta, nos termos do art. 49, V, da Constituição Federal, os efeitos do Decreto nº 12.467, de 23 de maio de 2025.","d":"2025-05-26","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Requerimento","u":"2025-06-25","ds":"Apresentação do REQ n. 2398/2025 (Requerimento de Apensação), pelo Deputado Zucco (PL/RS), que \"Requer a apensação dos projetos que especifica ao Projeto de Decreto Legislativo n. 214/2025\".","id":"2516046","law":false,"r":"c"},{"t":"PL","n":"2335","y":"2025","e":"Institui o Dia Nacional do Patrimônio Histórico e Cultural dos Poloneses no Brasil.","d":"2025-05-15","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Apresentação de Proposição","u":"2026-06-11","ds":"Remessa ao Senado Federal por meio do Of. nº 413/2026/PS-GSE.","id":"2509462","law":false,"r":"m"},{"t":"PL","n":"2318","y":"2025","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para estabelecer como homicídio qualificado o crime praticado com a finalidade de interferir, restringir ou manipular o processo eleitoral ou o exercício regular do mandato.","d":"2025-05-14","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-06-12","ds":"Recebimento pela CCJC.","id":"2509005","law":false,"r":"m"},{"t":"PL","n":"2265","y":"2025","e":"Revoga os arts. 359-L e 359-M do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 – Código Penal Brasileiro.","d":"2025-05-13","o":"approved_with_another_bill","s":"Arquivada","tr":"Prejudicialidade (Plenário)","u":"2025-12-09","ds":"Matéria aprovada na forma do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão). Esta proposição fica prejudicada, na forma do art. 191 do RICD.","id":"2508216","law":false,"r":"c"},{"t":"PEC","n":"17","y":"2025","e":"Acrescenta os §§ 11, 12 e 13 ao art. 144 da Constituição Federal, para instituir o piso salarial dos servidores policiais civis e militares e bombeiros militares.","d":"2025-04-23","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2025-04-23","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2499794","law":false,"r":"c"},{"t":"PL","n":"1784","y":"2025","e":"Dispõe sobre a imutabilidade do registro de sexo biológico nas certidões de nascimento e casamento e dá outras providências.","d":"2025-04-22","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-02-25","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 19/12/2025 a 25/02/2026). Não foram apresentadas emendas.","id":"2498918","law":false,"r":"c"},{"t":"PDL","n":"139","y":"2025","e":"Susta a Portaria MJSP nº 911, de 27 de março de 2025.","d":"2025-03-28","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-12-19","ds":"Designada Relatora, Dep. Erika Hilton (PSOL-SP).","id":"2490884","law":false,"r":"c"},{"t":"PL","n":"1263","y":"2025","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para estabelecer novas qualificadoras para o crime de furto e novas causas de aumento de pena para os crimes de roubo e receptação.","d":"2025-03-26","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-07-11","ds":"Recebimento pela CFT, apensado ao PL-3699/2023","id":"2490374","law":false,"r":"m"},{"t":"PDL","n":"118","y":"2025","e":"Susta a Portaria MAPA/SDA nº 1179, de 05 setembro de 2024.","d":"2025-03-11","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-11-13","ds":"Arquivado","id":"2486245","law":false,"r":"c"},{"t":"PL","n":"769","y":"2025","e":"Veda a censura prévia em ambientes virtuais e na imprensa, assegurando o exercício pleno da liberdade de expressão, nos termos da Constituição Federal e legislação vigente.","d":"2025-03-06","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-09-30","ds":"Designada Relatora, Dep. Bia Kicis (PL-DF).","id":"2485940","law":false,"r":"c"},{"t":"PL","n":"385","y":"2025","e":"Altera a Lei altera a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para dispor sobre a proibição de atividades comerciais dentro dos estabelecimentos penais.","d":"2025-02-11","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-08-19","ds":"Recebimento pela CCJC.","id":"2483604","law":false,"r":"c"},{"t":"PDL","n":"61","y":"2025","e":"Susta o Decreto nº 12.373, de 31 de Janeiro de 2025, que Regulamenta o exercício do poder de polícia da Fundação Nacional dos Povos Indígenas, nos termos do art. 49, V da Constituição Federal.","d":"2025-02-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-12-19","ds":"Designada Relatora, Dep. Juliana Cardoso (PT-SP), para o PDL 51/2025, ao qual esta proposição está apensada.","id":"2482788","law":false,"r":"c"},{"t":"PDL","n":"13","y":"2025","e":"Susta o Decreto Nº 12.341, de 23 de Dezembro de 2024 que “Regulamenta a Lei nº 13.060, de 22 de dezembro de 2014, para disciplinar o uso da força e dos instrumentos de menor potencial ofensivo pelos profissionais de segurança pública.”","d":"2025-02-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-11-10","ds":"Recebimento pela CCJC, apensado ao PDL-5/2025","id":"2482163","law":false,"r":"c"},{"t":"PEC","n":"51","y":"2024","e":"Altera o art. 7º e o Ato das Disposições Constitucionais Transitórias da Constituição Federal de 1988, para dispor sobre as condições especiais de trabalho do motorista profissional empregado no transporte rodoviário de cargas e de passageiros.","d":"2024-12-12","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2025-11-13","ds":"Encaminhada à publicação. Parecer da Comissão de Constituição e Justiça e de Cidadania Publicado em avulso e no DCD de 14/11/2025, Letra A.","id":"2479738","law":false,"r":"c"},{"t":"PEC","n":"44","y":"2024","e":"Altera o §9º do artigo 166 da Constituição Federal para destinar parte dos recursos oriundos das emendas individuais a programas e ações relacionados ao Esporte.","d":"2024-11-26","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Apresentação de Requerimento","u":"2025-11-07","ds":"Apresentação do REQ n. 4717/2025 (Requerimento de Inclusão ou Retirada de Assinatura em Proposição de Iniciativa Coletiva Obrigatória), pelo Deputado Carlos Sampaio (PSD/SP -Fdr PSDB-CIDADANIA), que \"Requer a inclusão de assinatura na PEC n. 44/2024\".","id":"2471383","law":false,"r":"c"},{"t":"PL","n":"4297","y":"2024","e":"Altera-se a Lei nº 11.460, de 21 de março de 2007 para dispor sobre plantio de organismos geneticamente modificados.","d":"2024-11-07","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2025-03-14","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 15/03/2025 PAG 47","id":"2467618","law":false,"r":"c"},{"t":"PLP","n":"177","y":"2024","e":"Revoga a Lei Complementar n.º 207, de 17 de maio de 2024.","d":"2024-10-31","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-02-24","ds":"Designado Relator, Dep. Geraldo Mendes (UNIÃO-PR).","id":"2466470","law":false,"r":"c"},{"t":"PEC","n":"29","y":"2024","e":"Altera a Constituição Federal para acrescentar no art. 5º texto sobre o marco temporal de início da vida humana explicitando de forma inequívoca a inviolabilidade do direito à vida, desde a sua concepção, bem como cria o inciso LXXX para especificar que a concepção é a junção do gameta masculino e o feminino, ocorrida durante a fecundação, em local propício para o desenvolvimento celular.","d":"2024-07-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2024-07-10","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2448752","law":false,"r":"c"},{"t":"PEC","n":"27","y":"2024","e":"Altera a Constituição Federal para acrescentar o Capítulo IX - Da Promoção Da Igualdade Racial, que institui o Fundo Nacional de Reparação Econômica e de Promoção da Igualdade Racial (FNREPIR) com o objetivo de promover a igualdade de oportunidades e a inclusão social dos brasileiros pretos e pardos, e dá outras providências","d":"2024-07-08","o":"status_not_published","s":"","tr":"Encerramentos","u":"2026-03-18","ds":"Matéria não apreciada em face do encerramento da Ordem do Dia.","id":"2447265","law":false,"r":"c"},{"t":"PL","n":"2660","y":"2024","e":"Obriga o Sistema Único de Saúde a garantir a realização da reversão da cirurgia de mudança de sexo.","d":"2024-07-02","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-02-25","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 19/12/2025 a 25/02/2026). Não foram apresentadas emendas.","id":"2444647","law":false,"r":"c"},{"t":"PEC","n":"24","y":"2024","e":"Altera os §§ 4º, 4°-B e 7º do art. 40 da Constituição Federal e os artigos 5º, 10, 23, 24 e 26 da Emenda Constitucional nº 103, de 2019, acrescenta o art. 144-A a Constituição e dá outras providências.","d":"2024-06-24","o":"in_progress","s":"Aguardando Constituição de Comissão Temporária","tr":"Expedição de Documento","u":"2026-08-26","ds":"Ato da Presidência: Cria Comissão Especial, nos termos do § 2º do art. 202 do Regimento Interno. Publicado em DCD Extra no dia 26/08/2026.","id":"2442880","law":false,"r":"c"},{"t":"PL","n":"2499","y":"2024","e":"Dispõe sobre a obrigatoriedade da notificação à autoridade policial, pelos hospitais, clínicas e unidades básicas de saúde, da interrupção de gestação decorrente de estupro e dá outras providências.","d":"2024-06-19","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2024-09-18","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 30/08/2024 a 18/09/2024). Não foram apresentadas emendas.","id":"2442393","law":false,"r":"c"},{"t":"PL","n":"2388","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) e a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para estabelecer punições mais severas aos crimes de estupro e estupro de vulnerável.","d":"2024-06-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-05-26","ds":"Apense-se a este o PL 1682/2026","id":"2440784","law":false,"r":"c"},{"t":"PL","n":"2317","y":"2024","e":"Altera as Leis 14.597, de 14 de junho de 2023, 7.716, de 5 de janeiro de 1989, e a 9.615, de 24 de março de 1998, para dispor sobre a cassação do registro de atleta profissional condenado por crime de racismo.","d":"2024-06-11","o":"rejected","s":"Arquivada","tr":"Arquivamento - Art.133 do RI","u":"2024-12-19","ds":"Arquivado nos termos do art. 133 do RICD (rejeição nas comissões de mérito).","id":"2439905","law":false,"r":"m"},{"t":"PL","n":"2058","y":"2024","e":"Cria a Lei de Criminalização do Revenge Porn e Sextorsão.","d":"2024-05-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-08","ds":"Recebimento pela CCJC.","id":"2436529","law":false,"r":"c"},{"t":"PL","n":"1904","y":"2024","e":"Acresce dois parágrafos ao art. 124, um parágrafo único ao artigo 125, um segundo parágrafo ao artigo 126 e um parágrafo único ao artigo 128, todos do Código Penal Brasileiro, e dá outras providências.","d":"2024-05-17","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2024-08-14","ds":"Aprovado o requerimento nº 44/2024,da Sra. Chris Tonietto que requer a realização de Audiência Pública para debater sobre o PL 1904/2024, que acresce dois parágrafos ao art. 124, um parágrafo único ao artigo 125, um segundo parágrafo ao artigo 126 e um parágrafo único ao artigo 128, todos do Código Penal Brasileiro, e dá outras providências.","id":"2434493","law":false,"r":"c"},{"t":"PL","n":"1633","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal para considerar como crime a criação de óbice ou embaraço fiscal, sanitário, ambiental ou administrativo, oimpedimento ou dificuldade ao serviço de combate ao perigo, de socorro ou salvamento, ou a entregade donativos ou o resgate às vítimas, durante a vigência de estado de calamidade pública.","d":"2024-05-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2024-05-13","ds":"Recebimento pela CCJC.","id":"2431790","law":false,"r":"c"},{"t":"PL","n":"1554","y":"2024","e":"Dispõe sobre a destinação de 50% do Fundo Partidário para implementação de medidas emergenciais em resposta calamidade pública decorrente das enchentes no Estado do Rio Grande do Sul.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificação de Despacho","u":"2024-05-09","ds":"Deferidos os Requerimentos 1460 e 1503, ambos de 2024.","id":"2430978","law":false,"r":"c"},{"t":"PL","n":"1511","y":"2024","e":"Altera a Lei nº 8.501, de 30 de novembro de 1992, para reduzir o prazo de espera para a destinação de cadáver não reclamado às instituições autorizadas, para impor a obrigação de sua conservação pelo prazo mínimo de 180 (cento e oitenta) dias e para modernizar as regras sobre divulgação de informações sobre os cadáveres não reclamados.","d":"2024-05-02","o":"status_not_published","s":"","tr":"Publicação de Proposição","u":"2024-05-07","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 08/05/2024.","id":"2430654","law":false,"r":"m"},{"t":"PDL","n":"224","y":"2024","e":"Susta o Decreto n.º 11.995, de 15 de abril de 2024, que institui o Programa Terra da Gente e dispõe sobre a incorporação de imóveis rurais no âmbito da Política Nacional de Reforma Agrária.","d":"2024-04-29","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-04-14","ds":"Designado Relator, Dep. Nikolas Ferreira (PL-MG), para o PDL 167/2024, ao qual esta proposição está apensada.","id":"2430387","law":false,"r":"c"},{"t":"PL","n":"1406","y":"2024","e":"Altera a Lei nº 12.187, de 29 de dezembro de 2009, para aprimorar o texto legislativo, que institui a Política Nacional sobre Mudança do Clima - PNMC, incluindo disposições sobre a não aceitação de acordos internacionais que possam representar restrições discriminatórias ao comércio internacional de produtos brasileiros.","d":"2024-04-23","o":"in_progress","s":"Pronta para Pauta","tr":"Retirada de Pauta","u":"2025-10-22","ds":"Retirado de pauta, por acordo, a pedido do Relator.","id":"2429195","law":false,"r":"c"},{"t":"PL","n":"1189","y":"2024","e":"Dispõe sobre a revogação do crédito fiscal decorrente de subvenção para implantação ou expansão de empreendimento econômico de que trata a Lei nº 14.789, de 29 de dezembro de 2023, e sobre o restabelecimento do tratamento tributário dado pela legislação anterior às subvenções governamentais.","d":"2024-04-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2026-07-08","ds":"Devolvido ao Relator, Dep. Paulo Guedes (PT-MG), para o PL 1009/2024, ao qual esta proposição está apensada.","id":"2425761","law":false,"r":"m"},{"t":"PL","n":"1116","y":"2024","e":"Altera a Lei nº 1.579, de 18 de março de 1952, que dispõe sobre as Comissões Parlamentares de Inquérito, para possibilitar o acompanhamento das providências adotadas após o encerramento dos trabalhos.","d":"2024-04-08","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-07-08","ds":"Parecer com Complementação de Voto, Dep. Chris Tonietto (PL-RJ), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação, com substitutivo.","id":"2424865","law":false,"r":"c"},{"t":"PLP","n":"29","y":"2024","e":"Dispõe sobre a regulamentação do imposto seletivo previsto na Emenda Constitucional nº 132, de 20 de dezembro de 2023, e dá outras providências.","d":"2024-03-19","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-03-10","ds":"Parecer do Relator, Dep. Nilto Tatto (PT-SP), pela rejeição.","id":"2422069","law":false,"r":"c"},{"t":"PDL","n":"24","y":"2024","e":"Este Decreto Legislativo susta os efeitos da Nota Técnica Conjunta n° 2/2024-SAPS/SAES/MS.","d":"2024-02-29","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-04-19","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 20/04/2024.","id":"2419066","law":false,"r":"c"},{"t":"PDL","n":"559","y":"2023","e":"Susta a Resolução nº 2, de 23 de novembro de 2023, do Comitê Gestor de Indicadores e Níveis de Eficiência Energética, do Ministério de Minas e Energia, que veda a fabricação, importação e comercialização de refrigeradores e congeladores com preços mais acessíveis à população.","d":"2023-12-21","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2026-06-09","ds":"Devolvido ao Relator, Dep. Clodoaldo Magalhães (PV-PE), para o PDL 488/2023, ao qual esta proposição está apensada.","id":"2416195","law":false,"r":"c"},{"t":"PL","n":"5596","y":"2023","e":"Altera o art. 6º-A da Lei nº 10.101, de 19 de dezembro de 2000, para permitir o trabalho em feriados nas atividades de comércio em geral.","d":"2023-11-21","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-12-05","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 06/12/2023.","id":"2405049","law":false,"r":"m"},{"t":"PEC","n":"62","y":"2023","e":"Altera o artigo 122 do Ato das Disposições Constitucionais Transitórias.","d":"2023-11-21","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2023-11-27","ds":"Apresentação do REQ n. 4064/2023 (Requerimento), pela Deputada Gleisi Hoffmann (PT/PR -Fdr PT-PCdoB-PV), que \"Requer a inclusão de coautoria na PEC 62/2023\".","id":"2404706","law":false,"r":"c"},{"t":"PDL","n":"392","y":"2023","e":"Susta o Decreto nº 11.764, de 31 de outubro de 2023, que altera a Tabela de Incidência do Imposto sobre Produtos Industrializados - TIPI, aprovada pelo Decreto nº 11.158, de 29 de julho de 2022.","d":"2023-11-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-11-07","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 08/11/2023.","id":"2401109","law":false,"r":"c"},{"t":"PL","n":"5021","y":"2023","e":"Institui a Lista de Organizações Terroristas, altera a Lei nº 13.260, de 16 de março de 2016, e dá outras providências.","d":"2023-10-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-07-07","ds":"Apensação da proposição PL 2730/2026 à proposição PL 972/2024.","id":"2396351","law":false,"r":"c"},{"t":"PL","n":"4894","y":"2023","e":"Dispõe sobre sanções políticas e econômicas relacionadas ao Hamas e ao Hezbollah, os classifica como grupos terroristas, e criminaliza manifestações de apoio a esses grupos.","d":"2023-10-09","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-10-14","ds":"Designada Relatora, Dep. Carla Dickson (PL-RN).","id":"2394641","law":false,"r":"c"},{"t":"PL","n":"4789","y":"2023","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, a Lei nº 8.069, de 13 de julho de 1990 - Estatuto da Criança e do Adolescente, a Lei nº 8.072, de 25 de julho de 1990 - Lei de Crimes Hediondos, a Lei nº 7.210, de 11 de julho de 1984 - Lei de Execução Penal, e o Decreto Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal, para recrudescer o tratamento penal destinado aos crimes sexuais contra crianças e adolescentes, visando prevenir e coibir o incentivo à pedofilia.","d":"2023-10-03","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-05-21","ds":"Parecer do Relator, Dep. Filipe Martins (PL-TO), pela aprovação do PL 4789/23, do PLs 20/24,1978/24, 3920/25, 4061/25, e 1201/26, apensados, com substitutivo.","id":"2392485","law":false,"r":"c"},{"t":"PDL","n":"344","y":"2023","e":"Susta o Decreto nº 11.716, de 26 de setembro de 2023, que Institui o Observatório da Democracia da Advocacia-Geral da União.","d":"2023-09-28","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-08-22","ds":"Designado Relator, Dep. Capitão Alberto Neto (PL-AM).","id":"2391921","law":false,"r":"c"},{"t":"PEC","n":"50","y":"2023","e":"Altera o art. 49 da Constituição Federal para estabelecer competência ao Congresso Nacional para sustar, por maioria qualificada dos membros da Câmara dos Deputados e do Senado Federal, decisão do Supremo Tribunal Federal transitada em julgado, que extrapole os limites constitucionais.","d":"2023-09-27","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Apresentação de Requerimento","u":"2025-12-03","ds":"Apresentação do REQ n. 5416/2025 (Requerimento), pelo Deputado Luiz Philippe de Orleans e Bragança (PL/SP), que \"Requer a criação da Comissão Especial destinada a proferir parecer sobre as Propostas de Emenda à Constituição nº 50, de 2023 e nº 28, de 2024, que tramitam em conjunto\".","id":"2391567","law":false,"r":"c"},{"t":"PDL","n":"337","y":"2023","e":"Susta a Resolução n° 2, de 19 de setembro de 2023, do Conselho Nacional dos Direitos das Pessoas Lésbicas, Gays, Bissexuais, Travestis, Trans., Queers, Intersexos.","d":"2023-09-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-07-30","ds":"Designado Relator, Dep. Daniel José (PODE-SP), para o PDL 335/2023, ao qual esta proposição está apensada.","id":"2390075","law":false,"r":"c"},{"t":"PEC","n":"38","y":"2023","e":"Modifica as regras dos regimes próprios de previdência social dos servidores dos municípios, objetivando o equilíbrio financeiro e atuarial dos regimes e a sustentabilidade fiscal desses entes, e dá outras providências.","d":"2023-08-16","o":"in_progress","s":"Aguardando Designação - Aguardando Devolução de Relator(a) que deixou de ser Membro","tr":"Saída de Relator(a) da Comissão - Sem Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) O Relator, Dep. Luiz Philippe de Orleans e Bragança, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2380340","law":false,"r":"c"},{"t":"PEC","n":"34","y":"2023","e":"Inclui dispositivos nos artigos 3º e 5º da Constituição da República Federativa do Brasil, estabelecendo o combate às drogas ilícitas como princípio fundamental e vedando expressamente a descriminalização do tráfico e a legalização de novas drogas recreativas.","d":"2023-08-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) A Relatora, Dep. Caroline de Toni, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2377463","law":false,"r":"c"},{"t":"PDL","n":"209","y":"2023","e":"Susta os efeitos da Resolução nº 510, de 26 de junho de 2023, do Conselho Nacional de Justiça, que “regulamenta a criação, no âmbito do Conselho Nacional de Justiça e dos Tribunais, respectivamente, da Comissão Nacional de Soluções Fundiárias e das Comissões Regionais de Soluções Fundiárias, institui diretrizes para a realização de visitas técnicas nas áreas objeto de litígio possessório e estabelece protocolos para o tratamento das ações que envolvam despejos ou reintegrações de posse em imóveis de moradia coletiva ou de área produtiva de populações vulneráveis”.","d":"2023-08-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-14","ds":"Recebimento pela CCJC, apensado ao PDL-182/2023","id":"2375447","law":false,"r":"c"},{"t":"PDL","n":"198","y":"2023","e":"Susta os efeitos da Resolução nº 715, de 20 de julho de 2023, do Conselho Nacional de Saúde, que trata das “orientações estratégicas para o Plano Plurianual (PPA) e para o Plano Nacional de Saúde (PNS) 2024-2027”.","d":"2023-07-28","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/09/2023.","id":"2374503","law":false,"r":"c"},{"t":"PDL","n":"189","y":"2023","e":"Susta o Decreto nº 11.615, de 21 de julho de 2023, que regulamenta a Lei nº 10.826, de 22 de dezembro de 2003, para estabelecer regras e procedimentos relativos à aquisição, ao registro, à posse, ao porte, ao cadastro e à comercialização nacional de armas de fogo, munições e acessórios, disciplinar as atividades de caça excepcional, de caça de subsistência, de tiro desportivo e de colecionamento de armas de fogo, munições e acessórios, disciplinar o funcionamento das entidades de tiro desportivo e dispor sobre a estruturação do Sistema Nacional de Armas - Sinarm.","d":"2023-07-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2374340","law":false,"r":"c"},{"t":"PL","n":"3507","y":"2023","e":"Altera a Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), para estabelecer o caráter absoluto da regra de impenhorabilidade prevista no inciso IV e no §2º do art. 833 e acrescer cláusula de vedação à sua mitigação por via judiciária.","d":"2023-07-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2026-04-29","ds":"Devolvido ao Relator, Dep. Helder Salomão (PT-ES), para o PL 5320/2019, ao qual esta proposição está apensada.","id":"2373507","law":false,"r":"m"},{"t":"PLP","n":"141","y":"2023","e":"Altera o inciso XIV do artigo 22, da Lei Complementar nº 64, de 18 de maio de 1990, para determinar que a sanção de inelegibilidade para as eleições a se realizarem seja nos 2 (dois) anos subsequentes à eleição.","d":"2023-07-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-06-11","ds":"Deferido o REQ 678/2025.","id":"2372482","law":false,"r":"c"},{"t":"PL","n":"3080","y":"2023","e":"Acrescenta novo parágrafo ao artigo 44 da Lei nº  9.394, de 20 de dezembro de 1996, que estabelece  as diretrizes e bases da educação nacional, com o  objetivo de permitir aos jovens aprovados em \nprocessos seletivos de universidades, públicas ou  privadas, o estudo no ensino superior mesmo que  menores de idade e ainda cursando o ensino médio.","d":"2023-06-14","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-06-09","ds":"Devolvido ao Relator, Dep. Diego Garcia (REPUBLIC-PR), para o PL 3405/2021, ao qual esta proposição está apensada.","id":"2369278","law":false,"r":"m"},{"t":"PL","n":"2501","y":"2023","e":"Dispõe sobre a criação do crime de censura e confisco de plataforma na lei 13.869 de 5 de setembro de 2019, que dispõe sobre os crimes de abuso de autoridade, e adiciona o crime de censura na lei 1.079 de 10 de abril de 1950, que dispõe sobre os crimes de responsabilidade, e dá outras providências.","d":"2023-05-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-10-15","ds":"Designado Relator, Dep. Pr. Marco Feliciano (PL-SP), para o PL 2782/2022, ao qual esta proposição está apensada.","id":"2361794","law":false,"r":"c"},{"t":"PL","n":"1881","y":"2023","e":"Estabelece que a cobrança, pela União, de tarifas, taxas e dos custos operacionais e de manutenção de obras ou serviços públicos vinculados ao aproveitamento econômico e social dos rios e das massas de água, nas regiões de secas periódicas, respeitará o prazo de carência de 5 (cinco) anos da entrada em operação do empreendimento, e altera a Lei nº 14.182, de 12 de julho de 2021, que dispõe sobre a desestatização da empresa Centrais Elétricas Brasileiras S.A. (Eletrobras).","d":"2023-04-13","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-04-17","ds":"Prazo de Vista Encerrado","id":"2356291","law":false,"r":"c"},{"t":"PDL","n":"122","y":"2023","e":"Susta a Portaria do Ministério da Justiça e Segurança Pública n° 351, de 12 de abril de 2023, que trata de medidas administrativas para prevenção à disseminação de conteúdos flagrantemente ilícitos, prejudiciais ou danosos por plataformas de redes sociais.","d":"2023-04-13","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-07","ds":"Designado Relator, Dep. Juscelino Filho (PSDB-MA).","id":"2356012","law":false,"r":"c"},{"t":"PEC","n":"6","y":"2023","e":"Dispõe sobre a autorização prévia pelo Congresso Nacional para operações de crédito de instituições financeiras oficiais federais  ou da República Federativa do Brasil que tenham por objeto a concessão de crédito a outros países ou suas sociedades estatais.","d":"2023-03-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-03-31","ds":"Recebimento pela CCJC, apensada à PEC-3/2023","id":"2351620","law":false,"r":"c"},{"t":"PEC","n":"5","y":"2023","e":"Acrescenta § 4º-A ao art. 150 da Constituição Federal, para dispor sobre a imunidade tributária de que tratam as suas alíneas “b” e “c” do inciso VI.","d":"2023-03-15","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-06-01","ds":"Remessa ao Senado Federal por meio do Of. nº 143/2026/SGM-P.","id":"2351506","law":false,"r":"c"},{"t":"PEC","n":"3","y":"2023","e":"Acrescenta o inciso XVIII ao art. 49, para estabelecer competência ao Congresso Nacional para autorizar operações de crédito por instituições financeiras controladas pela União, sempre que o objeto da operação vier a ser executado fora do País.","d":"2023-03-08","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2024-12-06","ds":"Encaminhada à publicação. Parecer da Comissão de Constituição e Justiça e de Cidadania Publicado em avulso e no DCD de 07/12/2024 PÁG 178, Letra A.","id":"2350568","law":false,"r":"c"},{"t":"PL","n":"446","y":"2023","e":"Altera a Lei nº 7.716, de 5 de janeiro de 1989, que define resultantes de preconceito de raça ou cor.","d":"2023-02-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificações","u":"2023-05-03","ds":"Deferido o Requerimento n° 511/2023.","id":"2348356","law":false,"r":"c"},{"t":"PDL","n":"39","y":"2023","e":"Susta os efeitos do Decreto Nº 11.366 de Janeiro de 2023 que suspendeu os registros para a aquisição e transferência de armas e de munições de uso restrito por caçadores, colecionadores, atiradores e particulares, restringe os quantitativos de aquisição de armas e de munições de uso permitido, suspende a concessão de novos registros de clubes e de escolas de tiro, suspende a concessão de novos registros de colecionadores, de atiradores e de caçadores, e institui grupo de trabalho para apresentar nova regulamentação à Lei nº 10.826, de 22 de dezembro de 2003.","d":"2023-02-09","o":"status_not_published","s":"","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2348336","law":false,"r":"m"},{"t":"PDL","n":"3","y":"2023","e":"Susta o Decreto nº 11.366, de 1º de janeiro 2023, que limita o registro e a aquisição de armas de fogos.","d":"2023-02-02","o":"in_progress","s":"Aguardando Parecer","tr":"Devolução ao(à) Relator(a)","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP)","id":"2345680","law":false,"r":"c"},{"t":"PDL","n":"397","y":"2022","e":"Susta os efeitos da Resolução da Diretoria  Colegiada - RDC nº 761, de 23 de novembro de 2022, da Agência Nacional de Vigilância  Sanitária - Anvisa, que altera a Resolução de  Diretoria Colegiada - RDC nº 456, de 17 de  dezembro de 2020, que dispõe sobre as  medidas a serem adotadas em aeroportos e  aeronaves em virtude da publicação da  Portaria GM/MS nº 913, de 22 de abril 2022,  do Ministro de Estado da Saúde, que declara  o encerramento da Emergência em Saúde  Pública de Importância Nacional (ESPIN) em  decorrência da infecção humana pelo novo  coronavírus - SARS-CoV-2.","d":"2022-12-02","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2024-06-26","ds":"Arquivado","id":"2340764","law":false,"r":"c"},{"t":"PEC","n":"26","y":"2022","e":"Altera o art. 96 da Constituição Federal, para dispor sobre a eleição dos órgãos diretivos dos Tribunais de Justiça.","d":"2022-11-01","o":"approved","s":"Transformado em Norma Jurídica","tr":"Apresentação de Proposição","u":"2024-12-03","ds":"Recebido Ofício nº 347/2024-CN que encaminha cópia de autógrafo da Emenda Constitucional 134/2024, promulgada, para o Arquivo da Câmara dos Deputados - PEC 26/2022.","id":"2336481","law":true,"r":"c"},{"t":"PL","n":"2605","y":"2022","e":"Acrescenta parágrafo 6º ao artigo 33 da Lei nº 9504, de 30 de setembro de 1997 para instituir nova modalidade de punição a institutos de pesquisa.","d":"2022-10-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2022-10-18","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 19/10/2022 PAG 177","id":"2335617","law":false,"r":"m"},{"t":"PL","n":"2465","y":"2022","e":"Cria o Sistema Nacional de Prevenção, Combate e Monitoramento de incêndios florestais – SISFLOBRAS e o Comando Nacional de Combate a Incêndios Florestais – CONFLOBRAS, altera a Lei nº 12.651, de 25 de maio de 2012, que dispõe sobre a proteção da vegetação nativa e a Lei nº 10.410, de 11 de janeiro de 2002, que cria e disciplina a carreira de Especialista em Meio Ambiente.","d":"2022-09-13","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-03-11","ds":"Designado Relator, Dep. Coronel Chrisóstomo (PL-RO).","id":"2335042","law":false,"r":"m"},{"t":"PL","n":"2100","y":"2022","e":"Altera a Lei nº 5.700, de 1º de setembro de 1971, para prever como crime a prática de condutas ultrajantes à Bandeira Nacional.","d":"2022-08-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2023-10-26","ds":"Designado Relator, Dep. Pedro Aihara (PATRIOTA-MG), para o PL 2271/2007, ao qual esta proposição está apensada.","id":"2332986","law":false,"r":"c"},{"t":"PL","n":"2098","y":"2022","e":"Altera os art. 35 e 36, da Lei n° 5.700, de 1 de setembro de 1971, que o dispõe sobre a forma e a apresentação dos Símbolos Nacionais, para alterar a sanção em atos que destruam ou ultrajam a bandeira, emblemas ou símbolos nacionais, e criar o tipo penal de destruição ou ultraje a bandeira, emblemas ou símbolos nacionais.","d":"2022-08-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2023-10-26","ds":"Designado Relator, Dep. Pedro Aihara (PATRIOTA-MG), para o PL 2271/2007, ao qual esta proposição está apensada.","id":"2332962","law":false,"r":"m"},{"t":"PEC","n":"17","y":"2022","e":"Visa a atualização e capacitação tecnológica das Forças Armadas, alterando o art. 167 da Constituição Federal, para retirar a limitação de dotações consignadas ao orçamento das Forças Armadas e acrescentando o art. 101 ao Ato das Disposições Constitucionais Transitórias, para vedar, quaisquer limitações à execução das dotações.","d":"2022-06-15","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2024-04-23","ds":"Parecer da Relatora, Dep. Bia Kicis (PL-DF), pela admissibilidade.","id":"2329063","law":false,"r":"c"},{"t":"PL","n":"1102","y":"2022","e":"Concede anistia aos fatos que especifica.","d":"2022-05-03","o":"in_progress","s":"Aguardando Designação - Aguardando Devolução de Relator(a) que deixou de ser Membro","tr":"Saída de Relator(a) da Comissão - Sem Parecer Apresentado","u":"2025-03-19","ds":"(Instalação da Comissão) O Relator, Dep. Rodrigo Valadares, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2025)","id":"2321377","law":false,"r":"c"},{"t":"PL","n":"747","y":"2022","e":"Altera a Lei nº 11.959, de 29 de junho de 2009, que dispõe sobre a Política Nacional de Desenvolvimento Sustentável da Aquicultura e da Pesca, regula as atividades pesqueiras, revoga a Lei nº 7.679, de 23 de novembro de 1988, e dispositivos do Decreto-Lei nº 221, de 28 de fevereiro de 1967, e dá outras providências.","d":"2022-03-29","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-06-11","ds":"Designado Relator, Dep. Pezenti (MDB-SC).","id":"2318860","law":false,"r":"m"},{"t":"PL","n":"633","y":"2022","e":"Tipifica o crime de submissão de criança ou adolescente a atuação cinematográfica, televisiva, teatral, de dança, ou de qualquer outra forma, comercial ou não, que fira sua dignidade sexual, mesmo que de modo implícito ou simulado.","d":"2022-03-18","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-10-01","ds":"Parecer da Relatora, Dep. Julia Zanatta (PL-SC), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação do PL 633/2022 e do PL 1183/2022, apensado, na forma do do Substitutivo da Comissão de Previdência, Assistência Social, Infância, Adolescência e Família.","id":"2318282","law":false,"r":"c"},{"t":"PL","n":"254","y":"2022","e":"Acrescenta o § 1º-A ao art. 20 da Lei nº 7.716, de 5 de janeiro de 1989, para prever o crime de falsa acusação de nazismo.","d":"2022-02-14","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2024-12-09","ds":"Prazo de Vista Encerrado","id":"2314518","law":false,"r":"c"},{"t":"PDL","n":"1132","y":"2021","e":"Susta a Resolução RE Nº 4.678, de 16 de dezembro de 2021, da Agência Nacional de Vigilância Sanitária (ANVISA), que aprova a aplicação da Vacina Comirnaty (Pfizer/Wyeth) em crianças entre 5 e 11 anos contra a COVID-19.","d":"2021-12-17","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Apresentação de Proposição","u":"2021-12-17","ds":"Apresentação do Projeto de Decreto Legislativo n. 1132/2021, pelo Deputado Diego Garcia  (PODE/PR) e outros, que \"Susta a Resolução RE Nº 4.678, de 16 de dezembro de 2021, da Agência Nacional de Vigilância Sanitária (ANVISA), que aprova a aplicação da Vacina Comirnaty (Pfizer/Wyeth) em crianças entre 5 e 11 anos contra a COVID-19\".","id":"2313194","law":false,"r":"c"},{"t":"PL","n":"4175","y":"2021","e":"Regulamenta o inciso XII do caput do art. 212-A da Constituição Federal, para instituir o piso salarial profissional nacional para os profissionais do magistério público da educação básica.","d":"2021-11-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-06-11","ds":"Designado Relator, Dep. João Maia (PP-RN), para o PL 698/2011, ao qual esta proposição está apensada.","id":"2308857","law":false,"r":"m"},{"t":"PL","n":"3702","y":"2021","e":"Dispõe sobre a exigência de\nAtestado de Vacinação no âmbito do \nPrograma Nacional de Imunizações,\naltera as Leis nº 6.259, de 30 de \noutubro de 1979, nº 10.406, de 10 de \njaneiro de 2002 e nº 13.979, de 6 de\nfevereiro de 2020, e dá outras \nprovidências.","d":"2021-10-21","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-02-07","ds":"Arquivado","id":"2303859","law":false,"r":"c"},{"t":"PL","n":"3477","y":"2021","e":"Inscreve o nome de Augusto Severo de Albuquerque Maranhão no Livro dos Heróis e Heroínas da Pátria.","d":"2021-10-06","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-08-03","ds":"Recebimento pela CCJC, apensado ao PL-5244/2019","id":"2302128","law":false,"r":"m"},{"t":"PL","n":"954","y":"2021","e":"Altera dispositivos da Lei nº 7.170, de 14 de dezembro de 1983, definindo termos e condutas.","d":"2021-03-18","o":"prejudged","s":"Arquivada","tr":"Arquivamento","u":"2021-05-04","ds":"Declarado prejudicado em face da aprovação da Subemenda Substitutiva Global ao Projeto de Lei nº 2.462, de 1991, adotada pela Relatora da Comissão Especial (Sessão Deliberativa Extraordinária de 04/05/2021 – 15h – 44ª Sessão).","id":"2274265","law":false,"r":"c"},{"t":"PL","n":"915","y":"2021","e":"Dispõe sobre a priorização dos profissionais de segurança pública para a Imunização contra a COVID-19.","d":"2021-03-16","o":"archived_reason_not_stated","s":"Arquivada","tr":"Devolução à CCP","u":"2022-12-08","ds":"Devolução à CCP.","id":"2273942","law":false,"r":"c"},{"t":"PL","n":"682","y":"2021","e":"Dispõe sobre a prática de cinoterapia, modalidade de terapia assistida por cães.","d":"2021-03-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2024-07-03","ds":"Encaminhada à publicação. Parecer da Comissão de Saúde Publicado em avulso e no DCD 04/07/2024 PAG 795, Letra B.","id":"2271944","law":false,"r":"c"},{"t":"PL","n":"356","y":"2021","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, para estabelecer nova hipótese de cometimento de crime em caso de censura de redes sociais, e acrescenta artigo à Lei nº 4.737, de 15 de julho de 1965 - Código Eleitoral, a fim de tipificar, também como crime eleitoral, a censura de redes sociais especificamente com este fim.","d":"2021-02-09","o":"in_progress","s":"Tramitando em Conjunto","tr":"Devolução à CCP","u":"2021-08-12","ds":"Devolução à CCP, conforme Memorando nº 180/2021 - COPER.","id":"2269848","law":false,"r":"m"},{"t":"PL","n":"5301","y":"2020","e":"Altera a Lei nº 9.504, de 30 de setembro de 1997, para vedar a divulgação de pesquisas eleitorais no período dos 15 (quinze) dias que antecedem as eleições, e responsabiliza os institutos de pesquisas pela divulgação e realização de pesquisas fraudulentas.","d":"2020-11-30","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2021-04-23","ds":"Apense-se a este(a) o(a) PL-314/2021.","id":"2265671","law":false,"r":"c"},{"t":"PL","n":"5115","y":"2020","e":"Altera o inciso III do artigo 10 da Lei nº 8.069, de 13 de julho de 1990, para ampliar o rol de doenças neonatais que devem ser obrigatória e gratuitamente rastreadas no Brasil.","d":"2020-11-06","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2021-08-27","ds":"Arquivado","id":"2265057","law":false,"r":"c"},{"t":"PL","n":"4897","y":"2020","e":"Revoga o parágrafo único do art.  316 do Código de Processo Penal (Decreto-Lei nº 3.689, de 3 de outubro de 1941), aprovado pela Lei nº 13.964, de 24 de dezembro de 2019.","d":"2020-10-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2026-02-13","ds":"Devolvido ao Relator, Dep. Alfredo Gaspar (UNIÃO-AL), para o PL 4888/2020, ao qual esta proposição está apensada.","id":"2264288","law":false,"r":"c"},{"t":"PDL","n":"406","y":"2020","e":"Susta atos de efeitos executivos, oriundos do Poder Judiciário, que exorbitam o poder regulamentar, na forma do art. 49, V da Constituição Federal","d":"2020-09-22","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2021-08-02","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 03/08/21 PAG 425","id":"2263229","law":false,"r":"m"},{"t":"PL","n":"4649","y":"2020","e":"Dispõe sobre o benefício da Tarifa Social de Energia Elétrica – TSEE para famílias que tenham entre seus membros portador de doença ou patologia cujo tratamento requeira consumo de energia elétrica de forma continuada.","d":"2020-09-18","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Despacho","u":"2022-03-22","ds":"Indeferido o Requerimento n. 2.705/2020, conforme despacho do seguinte teor: \"Indefiro o Requerimento n. 2.705/2020, nos termos do art. 128 do RICD. Publique-se.\"","id":"2263058","law":false,"r":"c"},{"t":"PL","n":"4341","y":"2020","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal para estabelecer nova hipótese sobre causa de especial aumento de pena, quanto aos crimes contra a Administração Pública, praticados por servidores públicos em tempo de pandemia ou estado de calamidade pública","d":"2020-08-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2021-02-10","ds":"Recebimento pela CCJC.","id":"2260901","law":false,"r":"m"},{"t":"PL","n":"4239","y":"2020","e":"Altera as redações do parágrafo único do artigo 83, dos artigos 213, caput e §§ 1º e 2º e 217-A, caput e §§ 3º e 4º, todos do Decreto-lei nº 2.848, de 7 de dezembro de 1940, e inclui o § 7º do artigo 112, da Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal).","d":"2020-08-18","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-05-28","ds":"Designado Relator, Dep. Capitão Alberto Neto (PL-AM), para o PL 6831/2010, ao qual esta proposição está apensada.","id":"2260542","law":false,"r":"m"},{"t":"PL","n":"4171","y":"2020","e":"Dispõe sobre o registro de dados referente à execução orçamentária e à movimentação financeira de recursos repassados pela União aos Estados, ao Distrito Federal e aos Municípios, no Sistema Integrado de Administração Financeira - SIAFI, do Governo Federal.","d":"2020-08-12","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Sem Parecer Apresentado","u":"2023-01-31","ds":"(Fim de Legislatura) O Relator, Dep. Paulo Ganime, deixou de ser membro da Comissão","id":"2259909","law":false,"r":"c"},{"t":"PL","n":"3803","y":"2020","e":"Altera a Lei nº 13.982, de 12 de abril de 2020, a fim de prever causa de aumento para crimes de estelionato, falsidade ideológica, certidão ou atestado ideologicamente falso, falsidade material de atestado ou certidão, peculato, concussão, corrupção passiva e corrupção ativa, bem como, determinar a restituição de valores recebidos indevidamente, quando a conduta tiver impacto sobre as medidas excepcionais de proteção social decorrente do período de enfrentamento ao coronavírus (Covid-19).","d":"2020-07-15","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-05-28","ds":"Arquivado","id":"2257736","law":false,"r":"c"},{"t":"PL","n":"3721","y":"2020","e":"Acresce e dá nova redação a dispositivos da Lei nº 9.504, de 30 de setembro de 1997.","d":"2020-07-08","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2021-02-10","ds":"Recebimento pela CCJC.","id":"2257272","law":false,"r":"m"},{"t":"PL","n":"3395","y":"2020","e":"Acrescenta o art. 21-A à Lei nº 12.965, de 23 de abril de 2014 (Marco Civil da Internet), proibindo os provedores de plataformas digitais de remover conteúdos publicados por seus usuários, salvo por força de cumprimento de ordem judicial.","d":"2020-06-18","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2021-11-23","ds":"Apense-se a este(a) o(a) PL-3700/2021.","id":"2255564","law":false,"r":"c"},{"t":"PL","n":"2996","y":"2020","e":"Acrescenta dispositivos à Lei nº 13.869, de 5 de setembro de 2019, à Lei nº 1.079, de 10 de abril de 1950, ao Decreto-Lei nº 201, de 27 de fevereiro de 1967 e à Lei nº 13.979, de 6 de fevereiro de 2020, para caracterizar como crime de abuso de autoridade e como crime de responsabilidade a violação de direitos individuais constitucionais durante tempos de paz, impedindo a liberdade de locomoção e o exercício de outras garantias.","d":"2020-05-29","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-05-25","ds":"Parecer do Relator, Dep. Capitão Alden (PL-BA), pela aprovação deste, na forma do substitutivo.","id":"2254073","law":false,"r":"c"},{"t":"PL","n":"2970","y":"2020","e":"Dispõe sobre o compartilhamento de informações, nos estabelecimentos de saúde públicos e privados.","d":"2020-05-28","o":"status_not_published","s":"","tr":"Notificações","u":"2024-02-09","ds":"Devolvida à Relatora, Dep. Adriana Ventura (NOVO-SP), em virtude da apensação do PL 65/2024., para o PL 5875/2013, ao qual esta proposição está apensada.","id":"2254017","law":false,"r":"c"},{"t":"PL","n":"2551","y":"2020","e":"Altera o Artigo 22 e inclui um parágrafo à Lei nº 13.146, de 6 de julho de 2015, que “institui a Lei Brasileira de Inclusão da Pessoa com Deficiência (Estatuto da Pessoa com Deficiência)”.","d":"2020-05-11","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2023-08-11","ds":"Encaminhada à publicação. Parecer da Comissão de Saúde Publicado em avulso e no DCD de 12/08/2023, Letra B.","id":"2252117","law":false,"r":"c"},{"t":"PL","n":"663","y":"2020","e":"Acrescenta o art. 60-A à Lei nº 9.096, de 19 de setembro de 1995, bem como acrescenta o art. 105-B à Lei 9.504 de 30 de setembro de 1997, para destinação dos fundos partidário e eleitoral ao combate e prevenção da pandemia COVID-19.","d":"2020-03-17","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-05-28","ds":"Arquivado","id":"2239371","law":false,"r":"c"},{"t":"PL","n":"649","y":"2020","e":"Altera a Lei nº 13.487, de 6 de outubro de 2017, para destinar os recursos do Fundo Especial de Financiamento de Campanha (FEFC) para o combate, controle e prevenção do agente viral \" nCov-2019\", da família coronavírus.","d":"2020-03-17","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-05-28","ds":"Arquivado","id":"2239122","law":false,"r":"c"},{"t":"PL","n":"591","y":"2020","e":"Altera  dispositivos da lei nº 9.424 de dezembro de 1996 e da Lei nº 9.766, de 18 de dezembro de 1998, para dispor sobre a distribuição nacional dos recursos do Salário-Educação de acordo com as matrículas da educação básica.","d":"2020-03-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2022-12-06","ds":"Recebimento pela CCJC, apensado ao PL-347/2019","id":"2238677","law":false,"r":"m"},{"t":"PL","n":"95","y":"2020","e":"Altera a Lei nº 9.434, de 4 de fevereiro de 1997, que dispõe sobre a remoção de órgãos, tecidos e partes do corpo humano para fins de transplante e tratamento, para permitir a doação recíproca de órgãos e tecidos (transplante cruzado).","d":"2020-02-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Aprovação de Urgência (154, 155 ou 64 CF)","u":"2024-11-13","ds":"Alteração do Regime de Tramitação desta proposição em virtude da alteração do regime do PL 1658/2024, por ter sido aprovado o REQ 1528/2024 que está apensado ao primeiro.","id":"2236479","law":false,"r":"c"},{"t":"PL","n":"6407","y":"2019","e":"Altera a Lei nº 6.932, de 7 de julho de 1981, para dispor sobre pontuação adicional no processo de seleção pública dos Programas de Residência Médica.","d":"2019-12-11","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-03-31","ds":"O Relator, Dep. Allan Garcês, deixou de ser membro da Comissão","id":"2233642","law":false,"r":"c"},{"t":"PL","n":"6076","y":"2019","e":"Altera o art. 36 da Lei nº 13.606/2018 para permitir a renegociação de dívidas de operações de crédito rural e dá outras providências","d":"2019-11-20","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-09-26","ds":"Recebimento pela CFT, apensado ao PL-4347/2019","id":"2230041","law":false,"r":"c"},{"t":"PL","n":"2159","y":"2019","e":"Altera a Lei nº 9.096, de 19 de setembro de 1995, para estabelecer nova hipótese de justa causa para a desfiliação partidária e novas hipóteses de cancelamento de registro civil e estatuto de partido político.","d":"2019-04-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2023-05-26","ds":"Apense-se a este(a) o(a) PL-1993/2023.","id":"2197276","law":false,"r":"m"},{"t":"PL","n":"1896","y":"2019","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, e a Lei nº 12.850, de 2 de agosto de 2013, para estabelecer novas hipóteses de circunstâncias agravantes e de causa de aumento de pena no crime de organização criminosa.","d":"2019-03-29","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2022-03-17","ds":"Apense-se a este(a) o(a) PL-405/2022.","id":"2196123","law":false,"r":"m"},{"t":"PL","n":"1777","y":"2019","e":"Altera as Leis n° 7.116, de 1983, nº 9.454, de 1997, e n° 13.444, de 2017, para estabelecer a adoção de número único para os documentos que especifica.","d":"2019-03-27","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2020-12-22","ds":"Desapensação automática deste do PL 1.422/2019, principal, em face da declaração de prejudicialidade deste e do seu consequente arquivamento (Sessão Deliberativa Extraordinária Virtual de 22/12/2020 - 16h53 - 139ª Sessão).","id":"2195526","law":false,"r":"c"}];
